window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["anki:ginecologia-doencas-de-vulva-e-vagina"]={"block":"anki:ginecologia-doencas-de-vulva-e-vagina","label":"Anki · Doenças de Vulva e Vagina","count":100,"questions":[{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-bfbf7f12f74c00b3","number":"0201x","sourceNumber":"0201x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Mulher, 58a, com quadro de prurido vulvar crônico há 10 anos, comparece em consulta de retorno para avaliação de resultado de biopsia de lesão vulvar, cujo diagnóstico foi neoplasia intraepitelial diferenciada. Exame ginecológico:\n(Figura 11, anexo. Área biopsiada destacada).\n\nO FATOR FREQUENTEMENTE ASSOCIADO A ESTE DIAGNÓSTICO É:","options":{"A":"Líquen escleroso da vulva.","B":"Papilomavírus humano tipos 6 e 11.","C":"Papilomavírus humano tipos 16 e 18.","D":"Doença de Paget invasiva."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":["question_bank/media/ginecologia-doencas-de-vulva-e-vagina/paste-dcfdaa988e1ff7e14f49b54b5ef372e326fdeecd.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314725","ankiGuid":"v`lb+?`I1>"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-1834d60c40498020","number":"0202x","sourceNumber":"0202x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Mulher de 68 anos, queixa-se de prurido vulvar há cerca de 8 meses. A inspeção genital está representada na imagem.\n\nDiante do quadro clínico e do exame físico, qual a melhor conduta?","options":{"A":"Exérese completa com margem de 3 mm.","B":"Biópsia incisional da borda da lesão.","C":"Corticosteroide de alta potência.","D":"Antibioticoterapia com penicilina benzatina."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":["question_bank/media/ginecologia-doencas-de-vulva-e-vagina/paste-e4a867b76cfdb5c66738cce54a4d8ff56e418188.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314728","ankiGuid":"uC(g51hp@a"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-3a01edfc50324e57","number":"0203x","sourceNumber":"0203x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"O câncer de vulva representa 3-5 % das neoplasias ginecológicas malignas, chegando até 8%, em razão do aumento da expectativa de vida. Em relação ao câncer de vulva, assinale a alternativa correta.","options":{"A":"Menarca precoce e menopausa tardia são fatores de risco.","B":"A via carcinogênica mais importante é a HPV induzida.","C":"O sintoma mais comum é o prurido de longa duração.","D":"O carcinoma escamoso de vulva queratinizante é o que ocorre em mulheres jovens.","E":"O atual sistema de estadiamento é clínico."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314729","ankiGuid":"nc$wek(7(B"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-946e2a2eb8b0e988","number":"0204x","sourceNumber":"0204x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Uma paciente de sessenta anos de idade, G6P4A2, queixa-se de prurido vulvar há cerca de dois anos. Exame ginecológico: lesão hipopigmentada de 2 cm no terço médio do grande lábio esquerdo. Foi realizada uma biópsia da lesão, cujo diagnóstico foi o de NIV diferenciada. Com base nesse caso hipotético, é correto afirmar que a terapêutica recomendada é o(a)","options":{"A":"radioterapia, que, após a excisão da lesão, é necessária devido à multicentricidade da doença.","B":"ablação com laser.","C":"tratamento inicial com imiquimode.","D":"excisão, com bisturi, com margens.","E":"vulvectomia simples."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314730","ankiGuid":"xJJ8eSDXGp"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-3502da0b532dc2e7","number":"0205x","sourceNumber":"0205x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"A respeito do tratamento de líquen escleroso vulvar, deve-se considerar o uso tópico de:","options":{"A":"corticóide de alta potência","B":"estrogênio","C":"progesterona","D":"testosterona"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314731","ankiGuid":"n$Y:%jKW9?"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-880b504cc02917c6","number":"0206x","sourceNumber":"0206x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Primigesta, 16 anos, 21 semanas, refere lesões na vulva há 30 dias. Na consulta Unidade Básica de Saúde, a avaliação da genitália evidencia as lesões mostradas na figura 1.\n\nQual a melhor conduta para esse caso?","options":{"A":"Ácido tricloacético 80%.","B":"Podofilotoxina.","C":"Expectante.","D":"Imiquimode."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":["question_bank/media/ginecologia-doencas-de-vulva-e-vagina/paste-3f3c5604c2d77c3484c527b4e60e01cf77391618.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314732","ankiGuid":"N}g6Z%NHcs"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-45837c7febe96175","number":"0207x","sourceNumber":"0207x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Sobre as lesões da vulva, dentre as afirmações abaixo descritas, assinale a alternativa CORRETA.","options":{"A":"A vulvoscopia é dispensável na suspeita de líquen escleroatrófico","B":"O líquen escleroatrófico apresenta risco de malignização","C":"O líquen escleroatrófico está associado à exposição excessiva ao estrogênio","D":"O uso de corticoide é a primeira linha de tratamento no caso de líquen plano"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314733","ankiGuid":"r}fB_m1^Os"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-21b5c912e6e14075","number":"0208x","sourceNumber":"0208x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Paciente com 60 anos de idade apresenta prurido crônico vulvar, e seu exame físico apresenta mancha branca e espessa envolvendo toda a vulva. A conduta é:","options":{"A":"Citologia esfoliativa.","B":"Biópsia.","C":"Corticoide.","D":"Testosterona tópica."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314734","ankiGuid":"HoP_Uqp3ee"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-177506d172934469","number":"0209x","sourceNumber":"0209x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Paciente de 33 anos procura o pronto atendimento de ginecologia e obstetrícia (PAGO) do Hospital de Clínicas da UFPR com queixa de algia intensa, febre aferida acima de 38 ºC, sensação de bola na entrada da vagina e leucocitose de 24.000 cel/microL. Ao exame ginecológico, foi observado tumoração cística de 5 cm à direita, dolorosa, com edema e hiperemia de grandes e pequenos lábios vulvares, além de ponto de flutuação e linfadenopatia inguinal homolateral dolorosa. A conduta adequada para esse caso é:","options":{"A":"bartolinectomia associada com antibióticos de largo espectro.","B":"ablação com nitrato de prata, compressa morna e assepsia do local e controle.","C":"internação imediata, início de antibiótico de largo espectro e tratamento cirúrgico de drenagem.","D":"compressa morna, anti-inflamatórios e tratamento cirúrgico de bartolinectomia.","E":"tratamento ambulatorial com antibióticos de largo espectro e anti-inflamatórios."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314735","ankiGuid":"qVXyFdCKpi"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-7c28db50a7835891","number":"0210x","sourceNumber":"0210x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Segundo o estadiamento da Federação Internacional de Ginecologia e Obstetrícia 2009 (FIGO) para o carcinoma de vulva, as lesões com mais de 2 cm ou com invasão do estroma maior que 1 mm, limitadas à vulva ou ao períneo, com linfonodos negativos deve ser classificada em qual estágio?","options":{"A":"IA.","B":"IB.","C":"II.","D":"IIA.","E":"IVA."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314736","ankiGuid":"l>+>*|(&?f"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-7bdf82acb819b3f0","number":"0211x","sourceNumber":"0211x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"A respeito do líquen escleroso vulvar, assinale a alternativa correta.","options":{"A":"Geralmente apresenta manchas hipercrômicas simétricas.","B":"O propionato de testosterona a 8% tópico é a primeira linha do tratamento.","C":"A maioria dos casos ocorre em mulheres pós-menopáusicas.","D":"corticoterapia oral é o tratamento mais recomendado e com menor risco de recidiva.","E":"Sua duração é autolimitada e o prurido não é frequente."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314737","ankiGuid":"B<@KNs=f5*"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-16563d416d959ee8","number":"0212x","sourceNumber":"0212x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Mulher de 20 anos comparece à primeira consulta ginecológica com queixa de prurido vulvar ocasional há alguns dias. Relata corrimento vaginal de longa data, sem relação com fase do ciclo menstrual. Faz uso de contraceptivo injetável mensal desde a sexarca aos 17 anos. Ao exame, apresenta vulva sem hiperemia, com presença de pequenas lesões papilomatosas espiculadas, de coloração semelhante à pele, em região perineal. Conteúdo vaginal esbranquiçado, escasso, sem odor, não aderido às paredes vaginais. Colo sem lesões. Qual a conduta adequada a seguir?","options":{"A":"Coletar exame citopatológico.","B":"Solicitar genotipagem para HPV.","C":"Aplicar ácido tricloroacético a 90%.","D":"Realizar bacterioscopia a fresco do conteúdo vaginal."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314738","ankiGuid":"CH$?knv@@k"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-1f4877849b1b9296","number":"0213x","sourceNumber":"0213x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Nas afecções que acometem a vagina:","options":{"A":"A principal neoplasia maligna vaginal é o adenocarcinoma de células claras, que se manifesta na pós-menopausa.","B":"Cistos vaginais raramente se manifestam clinicamente e, quando ocorrem, têm grande chance de malignidade.","C":"Formações verrucosas são comuns, principalmente no 1/3 médio da vagina e se manifestam por sangramentos irregulares.","D":"Os quadros infecciosos são os mais prevalentes, principalmente a candidíase, a vaginose bacteriana e a infecção por HPV.","E":"Os prolapsos das paredes vaginais aumentam o risco de aparecimento de câncer na vagina, por alteração do pH."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314739","ankiGuid":"F=)(z)f27="},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-6f34268a8b384e7b","number":"0214x","sourceNumber":"0214x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Adolescente de 17 anos refere surgimento há quatro semanas de lesões assintomáticas na base do pênis, com extensão para raiz de coxas e hipogástrio (imagem a seguir). Tem história de contato sexual desprotegido há seis semanas.\n\nO diagnóstico e a proposta terapêutica são:","options":{"A":"molusco contagioso; curetagem.","B":"verruga genital (HPV); cauterização com ácido tricloroa-cético 90%.","C":"sífilis primária (cancro duro); penicilina benzatina 2400000 UI intramuscular dose única.","D":"herpes genital; aciclovir 400 mg cinco vezes por dia por 7 dias."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":["question_bank/media/ginecologia-doencas-de-vulva-e-vagina/paste-8db690fc09bfa69ba6adb8fa59d172e0a0611af7.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314740","ankiGuid":"fB1Nw,Pn)."},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-3faf6e0ab0a00318","number":"0215x","sourceNumber":"0215x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Em relação ao exame ginecológico está incorreto:","options":{"A":"O exame físico das mamas deve ser feito rotineiramente apenas após aos 40 anos de idade da paciente, ou quando houver queixa específica.","B":"Os dados relacionados à pilificação da paciente são importantes. Por exemplo, o hirsutismo pode estar associado à Síndrome dos Ovários Policísticos.","C":"Politelia é um termo usado para o achado de mamilos extranumerários.","D":"O carcinoma de mama geralmente propaga-se por via linfática, o que justifica a necessidade de inspeção e palpação de linfonodos axilares e supraclaviculares durante o exame das mamas.","E":"Edema, dor e vermelhidão no coxim gorduroso dos grandes lábios pode estar associado à bartolinite gonocócica."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314741","ankiGuid":"xV1BBnf29b"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-1820974cd2ab4582","number":"0216x","sourceNumber":"0216x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"A dermatose inflamatória de vulva descrita como lesão pruriginosa, hipocrômica, brilhante, nacarada, causando aderência na linha mediana e estreitando o introito vaginal é?","options":{"A":"Líquen escleroso","B":"Epitélio acetobranco","C":"Condiloma plano","D":"Vitiligo"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314742","ankiGuid":"vQ{pF^&of{"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-39f271c53eaadbca","number":"0217x","sourceNumber":"0217x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"A bactéria que mais comumente infecta o cisto e provoca o abscesso de glândula de Bartholin é a:","options":{"A":"estreptococo beta hemolítico","B":"Chlamydia trachomatis","C":"Neisseria gonorrhoeae","D":"Escherichia coli"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314743","ankiGuid":"fSNpoK,>2n"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-7d9d32815abfecfa","number":"0218x","sourceNumber":"0218x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Paciente de 60 anos com quadro de prurido vulvar há cerca de 6 meses. Já usou por conta própria creme de nistatina sem melhora. Ao exame físico observa-se lesão hipocrômica acometendo sulco interlabial e região perianal, além de um adelgaçamento de pequenos lábios. O diagnóstico clínico da paciente é:","options":{"A":"Vitiligo.","B":"Líquen simples.","C":"Doença de Paget vulvar.","D":"Líquen escleroso."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314744","ankiGuid":"gx(m$5Cvdq"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-a6cb99051a92f71a","number":"0219x","sourceNumber":"0219x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"A Condilomatose conhecida como tumor de Buscke-Lowenstein apresenta as seguintes características, EXCETO:","options":{"A":"É considerada variante de carcinoma espinocelular verrucoso.","B":"Associada geralmente aos HPVs 6 e 11.","C":"Adquirem tamanhos grandes com crescimento lento.","D":"Geralmente acometem indivíduos imunocompetentes."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314745","ankiGuid":"v&&[Y<E-[X"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-543cb3fae1f0957b","number":"0220x","sourceNumber":"0220x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Assinale a alternativa correta, a respeito do HPV.","options":{"A":"É frequente a transmissão por fômites, bem como durante o parto.","B":"Apesar de ser uma infecção rara, é importante devido ao potencial oncogênico.","C":"A prevalência é maior em mulheres acima de 30 anos.","D":"A maioria das infecções leva ao desenvolvimento de verrugas anogenitais.","E":"A imunização contra HPV faz parte do Calendário Nacional de Vacinação."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314746","ankiGuid":"rUbB%r!mao"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-694845e0ddc1c213","number":"0221x","sourceNumber":"0221x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"A moléstia de Paget da vulva é:","options":{"A":"Neoplásica.","B":"Inflamatória.","C":"Metaplásica.","D":"Degenerativa.","E":"Traumática."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314747","ankiGuid":"zs,Tfb[GJ"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-33ee116bef729a36","number":"0222x","sourceNumber":"0222x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Mulher, 35 anos, queixando-se de prurido intenso em genitália, apresenta, ao exame ginecológico, lesões em placa hipoacrômica, de aspecto nacarado, discretamente endurecida em vulva. Indique, respectivamente, o diagnóstico e tratamento corretos.","options":{"A":"Atrofia branca de Milian, clobetasol tópico.","B":"Liquen escleroatrófico, clotrimazol tópico.","C":"Atrofia branca de Milian, clotrimazol tópico.","D":"Liquen escleroatrófico, clobetasol tópico."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314748","ankiGuid":"e*I1-ft72,"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-88d504c85d894deb","number":"0223x","sourceNumber":"0223x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Maria, 60 anos, apresenta prurido vulvar há 6 meses. Ao exame: lesão hipocrômica em clitóris, pequenos lábios e perianal em formato de \"\"8\"\", além de pequena sinequia de pequenos lábios. Qual provável diagnóstico:","options":{"A":"Líquen plano.","B":"Líquen escleroso.","C":"Vitiligo.","D":"Psoríase."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314749","ankiGuid":"M>/8CR.8nE"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-3d8f346c081e6b85","number":"0224x","sourceNumber":"0224x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Sobre a Neoplasia Intraepitelial Vulvar (NIV) avalie as afirmativas: I- A vulvectomia pode ser utilizada como tratamento. II- A Doença de Paget da Vulva acomete principalmente mulheres brancas na pós-menopausa. III- O melanoma disseminado superficial é diagnóstico diferencial da Doença de Paget da Vulva. Estão corretas:","options":{"A":"Apenas a afirmativa I está correta.","B":"Apenas a afirmativa II está correta.","C":"Apenas a afirmativa III está correta.","D":"Apenas as afirmativas I e II estão corretas.","E":"As afirmativas I, II e III estão corretas."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314750","ankiGuid":"gc`&mx:I_9"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-6891f03823ff334f","number":"0225x","sourceNumber":"0225x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Mulher com vida sexual ativa, chega à emergência referindo prurido vulvar intenso, sensação de queimação local. Ao exame observam-se inúmeras verrugas vulvares. Conduta:","options":{"A":"Prescrever a vacina para o vírus HPV","B":"Internar e realizar exérese ampla das lesões","C":"Solicitar teste rápido para sífilis; se negativo, encaminhar ao ambulatório para cauterização das lesões","D":"Iniciar antibióticos"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314751","ankiGuid":"y{y7oYoC<?"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-114e26834966d606","number":"0226x","sourceNumber":"0226x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Uma mulher de 78 anos de idade apresenta lesão numular de 1,5 cm em grande lábio direito. Submeteu-se à biópsia incisional ambulatorial que revelou carcinoma espinocelular com invasão estromal de 0,5 mm. A conduta recomendada é","options":{"A":"Radioterapia locoregional exclusiva, uma vez que o risco cirúrgico é elevado.","B":"Vulvectomia simples direita e remoção do linfonodo sentinela inguinal isilateral.","C":"Vulvectomia radical e remoção do linfonodo sentinela inguinal bilateral.","D":"Ressecção ampliada da lesão com margem de 2cm, dispensando linfadenectomia.","E":"Cauterização química ou elétrica da lesão e excisão cirúrgica se houver recidiva."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314752","ankiGuid":"MJ8XGDi|V{"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-a3fce82335123486","number":"0227x","sourceNumber":"0227x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Uma adolescente de 15 anos de idade procura o ginecologista para orientação contraceptiva. Refere que seus pais desconhecem que tem atividade sexual e que não pretende contar a eles. Durante o exame ginecológico, são encontradas verrugas genitais suspeitas de HPV. Após esclarecer as dúvidas da jovem quanto à vida sexual com segurança, o ginecologista deve","options":{"A":"Prescrever contraceptivo, biopsiar e tratar as lesões suspeitas com autorização da paciente.","B":"Solicitar a presença de um familiar responsável para prescrever o contraceptivo e tratar as lesões.","C":"Prescrever o contraceptivo, mas solicitar a um responsável que autorize a realização da biópsia.","D":"Orientar o uso de preservativo, cauterizar as lesões verrucosas e esclarecer sobre a necessidade da presença de um adulto responsável para prescrição de medicamentos.","E":"Avisar os responsáveis a respeito da suspeita de HPV por se tratar de doença sexualmente transmissível antes de instituir qualquer tratamento."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314753","ankiGuid":"skoWwF6qbo"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-6781f938cb78f2c6","number":"0228x","sourceNumber":"0228x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"A glândula de Bartholin está localizada no terço interior dos grandes lábios. Quando seu ducto é obstruído, forma-se um cisto, geralmente assintomático, podendo eventualmente se manifestar como desconforto ou mesmo dor ao sentar ou nas relações sexuais. Qual a conduta diante de um caso:","options":{"A":"Se assintomático ou com sintomas leves, orientar quanto a benignidade do quadro e evitar banhos de assento","B":"Se assintomático ou com sintomas leves, orientar quanto a possível malignidade do quadro, observar e tratar com banhos de assento e analgésicos","C":"Se sintomático a cirurgia de marsupialização não é indicada","D":"Usar antibióticos apenas se suspeita de IST, presença de abscesso ou em caso de recorrências"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314754","ankiGuid":"fG>ltEW{UM"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-3ca338790c2182fa","number":"0229x","sourceNumber":"0229x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Paciente de 18 anos é atendida na USF com queixa de aparecimento de lesões, destacadas na figura abaixo.\n\nAssinale a alternativa correta:","options":{"A":"Trata-se de candidíase vulvar e o tratamento correto deverá utilizar fluconazol oral e creme vaginal contendo miconazol;","B":"Trata-se de infecção mista e o tratamento correto deverá utilizar tinidazol oral e creme vaginal contendo nistatina;","C":"Trata-se de condiloma, causado pelo HPV e o tratamento recomendado é a aplicação de gama-interferon, devido à quantidade maciça de lesões;","D":"Trata-se de de condiloma, causado pelo HPV e o tratamento recomendado é a aplicação de ácido tricloroacético em concentração não inferior a 80%;","E":"Não é possível definir a infecção, o correto seria utilização de creme vaginal contendo antifúngico, antibacteriano e antiprotozoário."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":["question_bank/media/ginecologia-doencas-de-vulva-e-vagina/paste-d3d6a5383726f3d318c4fd5be78ead33efc7c4ec.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314755","ankiGuid":"mZwP(YEB@x"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-eb46b8fd1308240f","number":"0230x","sourceNumber":"0230x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Mulher de 85 anos de idade queixa-se de prurido vulvar intermitente, há mais de três anos, que piorou nos últimos meses. Ao exame, observase pequena lesão ulcerada de 1 cm no grande lábio direito. Pela frequência, espera-se encontrar em exame histológico:","options":{"A":"Melanoma.","B":"Carcinoma basocelular.","C":"Sarcoma.","D":"Carcinoma escamoso."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314756","ankiGuid":"fmuhHEnbF-"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-8b232976af6e4195","number":"0231x","sourceNumber":"0231x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Menina de 9 anos, pré-púbere, apresenta prurido na região genital há quatro meses. Utilizou nistatina tópica sem melhora. Exame físico: área acrômica de quatro centímetros de diâmetro em região interna dos grandes lábios, com discretas fissuras. A principal hipótese diagnóstica e o respectivo tratamento são:","options":{"A":"vitiligo; fototerapia com UVA","B":"trauma local; investigar abuso sexual.","C":"líquen escleroso; corticosteroide tópico.","D":"esclerodermia; metotrexato oral."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314757","ankiGuid":"lOXR)=mL{d"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-184397bc55837e52","number":"0232x","sourceNumber":"0232x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Jovem, 16 anos de idade, conta que há 2 semanas surgiram lesões exofílicas em vulva, semelhantes a \"cristas de galo\". Ao exame: múltiplas verrugas genitais em topografia de lábios menores, bilateralmente (foto da lesão reproduzida a seguir).\n\nDiante da situação apresentada, indique a alternativa correta com relação à suspeita diagnóstica e ao tratamento, respectivamente, conforme o Protocolo Clínico e Diretrizes Terapêuticas do Ministério da Saúde.","options":{"A":"Herpes genital; aciclovir","B":"Donovanose; doxiciclina","C":"Condiloma acuminado; ácido tricloroacético","D":"Síflis, penicilina benzatina","E":"Linfogranuloma venéreo; azitromicina"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":["question_bank/media/ginecologia-doencas-de-vulva-e-vagina/paste-c9dd60d423e2c3a7f414b7f1f6fdc2befc6b5407.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314758","ankiGuid":"dpb(-,9v{<"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-f5d64ded41cb8a39","number":"0233x","sourceNumber":"0233x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Paciente de 25 anos de idade, gestante de 30 semanas, apresentando condiloma acuminado em vulva. Dos tratamentos abaixo, qual é contra-indicado para esta paciente?","options":{"A":"Ácido tricloro-acético (ATA) a 50%","B":"Eletrocauterização","C":"5-fluorouracil","D":"Excisão das lesões com bisturi de alta frequência"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314759","ankiGuid":"c0ELhBk_ZC"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-cf89e05264108f81","number":"0234x","sourceNumber":"0234x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Mulher de 65 anos com carcinoma de vulva invasivo com 3 cm de diâmetro, sem evidência de disseminação linfática. Qual deve ser o tratamento inicial de escolha?","options":{"A":"Quimioterapia.","B":"Radioterapia.","C":"Vulvectomia simples.","D":"Vulvectomia radical sem linfadenectomia inguinal.","E":"Vulvectomia radical parcial com linfadenectomia inguinal bilateral."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314760","ankiGuid":"w}[7fjW=)<"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-723a2b6f55b16e6d","number":"0235x","sourceNumber":"0235x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Paciente de 52 anos, na pós-menopausa, refere prurido vulvar há um ano associado à dispareunia, com espessamento da pele e fissuras. Exame físico: mancha hipocrômica em grandes lábios com extensão para região perineal e atrofia de pequenos lábios. Realizada biópsia com diagnóstico de líquen escleroso vulvar. A terapêutica inicial, mais adequada, para esta paciente é:","options":{"A":"Estrogenioterapia local","B":"Corticoide tópico de alta potência.","C":"Hidratantes ou emolientes locais.","D":"Anti-histamínico por via oral."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314761","ankiGuid":"Q$!Q>@Z]f5"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-2f2a21df9a8fed8b","number":"0236x","sourceNumber":"0236x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"A neoplasia intraepitelial da vulva, mais conhecida pela sigla VIN, que deriva da sua denominação inglesa “vulvar intraepithelial neoplasia”, é uma entidade patológica reconhecida há mais de 20 anos pela International Society for Study of Vulvo-vaginal Diseases (ISSVD). O interesse médico pela VIN se acentuou na última década, dado o reconhecimento do crescente aumento da incidência da doença, especialmente em mulheres jovens, e pelo desenvolvimento de novas terapêuticas médicas dirigidas ao tratamento primário. Na neoplasia de vulva, as metástases para linfonodos intrapélvicos são mais frequentes quando a lesão localiza-se","options":{"A":"nos pequenos lábios.","B":"nos grandes lábios.","C":"no clitóris.","D":"na comissura posterior."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314762","ankiGuid":"f`?7#_tEXJ"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-ae7d31c1262584ef","number":"0237x","sourceNumber":"0237x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Paciente, 50 anos, relata desconforto acompanhado de prurido na região anogenital há 8 meses. História de hipertireoidismo. Ao exame físico, hipocromia vulvar e perineal, áreas de queratose e atrofia dos pequenos lábios, coalescência com os grandes lábios. Hipótese diagnóstica:","options":{"A":"Candidíase.","B":"Hipoestrogenismo.","C":"Esclerodermia.","D":"Líquen escleroatrófico.","E":"Líquen crônico simples."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314763","ankiGuid":"CQ;Y,I#~]0"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-d2391a558f631ffe","number":"0238x","sourceNumber":"0238x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Paciente, 20 anos, comparece no serviço de ginecologia devido aparecimento de verrugas genitais. MAC:ACO. Ao exame físico, múltiplos pequenos condilomas na vulva. Realizado os testes rápidos para ISTs, reagente para sífilis. Fez VDRL, não reagente. História de tratamento para sífilis. Marque a alternativa correta quanto as condutas, respectivamente:","options":{"A":"ATA; tratar sífilis.","B":"Podofilina; tratar sífilis.","C":"Imiquimode; não tratar sífilis.","D":"Ressecção das lesões vulvares; não tratar sífilis.","E":"Laser; tratar sífilis."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314764","ankiGuid":"H]Tk;$3[;}"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-b45490885eb3c008","number":"0239x","sourceNumber":"0239x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"A neoplasia de vulva é incomum e o tipo histopatológico mais prevalente é o epidermoide. A disseminação neoplástica pode ocorrer por três vias: linfática, hematogênica e locorregional. Os linfáticos da vulva e do terço distal da vagina drenam geralmente para os linfonodos:","options":{"A":"inguinais superficiais","B":"inguinais profundos","C":"femorais profundos","D":"ilíacos internos"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314765","ankiGuid":"C<d=9/Fg/+"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-62d8f0023703bc8a","number":"0240x","sourceNumber":"0240x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Lactente de 10 meses foi levada ao pediatra com quadro de lesões verrucosas perianais de início há um mês, que foram aumentando em quantidade. A mãe, 14 anos, refere que ele nasceu no parto vaginal, assistido por pediatra, sem complicações, permanecendo em aleitamento materno exclusivo até 2 meses. Por vezes, a bebê ficava sozinha com o avô paterno. Foi verificado que o calendário vacinal está em dia, e que no cartão de acompanhamento pré-natal há registro de oito consultas, sem intercorrências. O laudo de exame colposcópico, realizado com seis meses de gestação, mostrou lesão NIC grau I. Ao exame físico, a criança está em bom estado geral, mas apresenta lesões condilomatosas acuminadas em região perianal. O restante do exame físico apresentou resultado normal. Diante desse caso, a principal hipótese diagnóstica é de:","options":{"A":"Infecção por HPV de transmissão perinatal.","B":"Infecção por HPV por abuso sexual.","C":"Sífilis por abuso sexual.","D":"Sífilis congênita."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314766","ankiGuid":"P_VxHXTE,a"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-53fe4b8f46ef3f2c","number":"0241x","sourceNumber":"0241x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Mulher, 35 anos, procura atendimento médico com queixa de prurido vulvar. Ao exame clícnico apresenta lesões policrômicas, papulosas em placas confluentes acometendo 1/3 médio de grande lábio esquerdo. É submetida à biópsia que revela tratar-se de lesão intraepitelial escamosa vulvar de alto grau (NIV usual). O tipo de HPV mais comumente envolvido e o respectivo tratamento indicado são os seguintes:","options":{"A":"HPV 11/ vulvectomia parcial.","B":"HPV 11/ vulvectomia total com linfadenectomia inguinal do lado da lesão.","C":"HPV 16 / excisão ampla com linfadenectomia inguinal do lado da lesão.","D":"HPV 18 / excisão ampla com linfadenectomia inguinal do lado da lesão.","E":"HPV 16 / excisão ampla da lesão com margem de segurança."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314767","ankiGuid":"EeLS&Z{nYX"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-1843c56de3914d55","number":"0242x","sourceNumber":"0242x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"A pele e o tecido subcutâneo do monte púbico são irrigadas pela artéria","options":{"A":"uterina.","B":"vaginal.","C":"femoral.","D":"pudenda externa.","E":"glútea inferior."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314768","ankiGuid":"r_0z;@`fX5"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-30d875b4d2c1ca69","number":"0243x","sourceNumber":"0243x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Paciente de 55 anos comparece à consulta com queixa de prurido vulvar há 1 ano. Realizou vários tratamentos por conta própria com diferentes cremes vaginais, sem sucesso. Faz tratamento para diabetes e hipotireoidismo. Está divorciada, é sexualmente ativa e refere última menstruação há 3 anos. Ao exame ginecológico você observa uma área hipopigmentada e atrófica envolvendo introito vaginal, clitóris, pequenos lábios, região perianal e face interna dos grandes lábios, em formato de ampulheta. Qual o tratamento mais adequado?","options":{"A":"Fluconazol 150 mg via oral.","B":"Estriol 1% creme vaginal.","C":"Cetoconazol 2% + betametasona 0,05% tópico.","D":"Clobetasol 0,05% tópico."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314769","ankiGuid":"CxZO8d(Zcd"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-110748979d810b8e","number":"0244x","sourceNumber":"0244x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Dentre as patologias vulvares, as mais comuns se manisfestam pela presença de úlceras ou verrugas. Marque a afirmativa INCORRETA.","options":{"A":"Todas as mulheres com úlceras genitais devem ser submetidas a teste sorológico para sífilis, objetivando prevenir a forma terciária desta doença e a sífilis congênita.","B":"Vesículas agrupadas misturadas a pequenas úlceras, sobretudo com história prévia dessas mesmas lesões, são quase sempre patognomônicas de herpes genital.","C":"As verrugas genitais externas são uma manifestação de infecção pelo HPV e o objetivo do tratamento deve ser a erradicação da infecção viral, por seu risco oncogênico.","D":"Úlcera única, indolor, de bordo regular e endurecido é sugestiva de sífilis enquanto úlcera única ou múltipla, dolorosa, de bordo irregular com linfadenopatia inguinal sugere cancróide."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314770","ankiGuid":"jswsXrv8lN"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-065ce23462d14081","number":"0245x","sourceNumber":"0245x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Os linfonodos mais frequentemente acometidos, em relação ao câncer de vulva são os:","options":{"A":"Pelvicos","B":"Para-aorticos","C":"Inguinofemorais","D":"Ilíacos externos"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314771","ankiGuid":"em2:b%=W>W"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-721bb6f2b15206a7","number":"0246x","sourceNumber":"0246x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Assinale a alternativa correto:","options":{"A":"A ressonância magnética é a modalidade de imagem preferencial para a avaliação inicial de massas anexiais.","B":"A vaginose pela Gardnerella é uma condição em que há um predomínio de bactérias aeróbias e não é causa importante de prurido vulvar.","C":"O líquen escleroso é uma inflamação crônica cujo sintoma chave é o prurido vulvar.","D":"A adenomiose é a infiltração profunda do miométrio por tecido endometrial (glandular e estromal) sendo o diagnóstico suspeitado pelos achados histológicos da peça cirúrgica.","E":"A doença inflamatória pélvica caracteriza-se por dor no abdômen inferior, febre e hemograma alterado, sendo o seu diagnóstico fácil e preciso."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314772","ankiGuid":"uyH)Fp{&Jr"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-2967339e76084988","number":"0247x","sourceNumber":"0247x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Sobre as neoplasias ginecológicas, assinale a opção CORRETA.","options":{"A":"A disseminação por via linfática é a principal forma de propagação do câncer de ovário.","B":"O câncer de endométrio possui lesão precursora estabelecida e passível de prevenção.","C":"O câncer de vulva é mais prevalente em mulheres jovens e tem o HPV como seu principal agente etiológico.","D":"A quimioterapia tem papel importante no tratamento do câncer do colo uterino.","E":"A radioterapia não tem indicação no tratamento do câncer de ovário."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314773","ankiGuid":"n3wR/EJ0EC"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-e858c4ad0ec2a519","number":"0248x","sourceNumber":"0248x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Sobre o carcinoma da vulva, assinale a alternativa CORRETA:","options":{"A":"O tipo histológico mais frequente é o carcinoma queratinizante.","B":"O melanoma de vulva é o quarto câncer invasivo de vulva mais frequente.","C":"A Doença de Paget vulvar invasiva não está relacionada as células apócrinas.","D":"No tumor de Buscke Löwestein de comportamento maligno, não se deve indicar radioterapia porque os raios ionizantes provocam transformação da célula diplóide em aneuplóide.","E":"O tratamento preconizado para o Adenocarcinoma de glândula de Bartholin é a Bartholinectomia associado a radioterapia local."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314774","ankiGuid":"NSGznZCF&x"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-09893bb853328d18","number":"0249x","sourceNumber":"0249x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Mulher de 71 anos, com carcinoma escamoso da vulva e lesão de 1 cm, adjacente ao meato uretral e com metástases para linfonodos inguinais bilaterais. O estadiamento correto pelos critérios da FIGO (Federação Internacional de Ginecologia e Obstetrícia) será:","options":{"A":"III A","B":"IV A","C":"II B","D":"III B"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314775","ankiGuid":"DmR!EL,V|X"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-d71e542322c4cfa3","number":"0250x","sourceNumber":"0250x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Coco gram negativo que pode causar Bartholinite,","options":{"A":"estafilococo.","B":"gonococo.","C":"trichomonas.","D":"mobiluncus."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314776","ankiGuid":"B&q>Pk6qQo"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-4fa3f8a48d591845","number":"0251x","sourceNumber":"0251x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Em um quadro de Bartholinite aguda, o tratamento imediato mais recomendado é:","options":{"A":"Bartholinectomia.","B":"Punção e antibiótico.","C":"Antibioticoterapia e calor local.","D":"Drenagem e antibiótico."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314777","ankiGuid":"OW7yt+_rp5"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-b55dbdd041fc96b4","number":"0252x","sourceNumber":"0252x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Sobre a anatomia da vulva, pode-se afirmar que:","options":{"A":"As glândulas de Skene se localizam na superfície interna dos grandes lábios;","B":"As glândulas de Bartholin originam-se do ducto menosonéfricos;","C":"Os lábios maiores são homólogos à próstata;","D":"Os pequenos retalhos do hímen, restantes após o parto são chamados de carúnculas"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314778","ankiGuid":"mDPe`~WtA#"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-eae70eb1efd9df1e","number":"0253x","sourceNumber":"0253x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Paciente 52 anos, refere prurido vulvar resistente ao uso de medicamentos. Ao exame é observado diminuição da gordura subcutânea da vulva, atrofia das formações vulvares, os pequenos lábios ausentes e sepultamento do clitóris. Qual o provável diagnóstico?","options":{"A":"Líquen escleroso.","B":"Líquen plano.","C":"Candidíase vaginal crônica.","D":"Distrofia hiperplásica.","E":"Doença de Paget."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314779","ankiGuid":"jCV&nnC/S*"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-9b27bf8cb8990d8a","number":"0254x","sourceNumber":"0254x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Jéssica, 11 anos, é levada à consulta com Pediatra devido ao surgimento de lesões papulares umbilicadas, de tamanhos variados (3 mm a 1 cm de diâmetro), em abdome, há cerca de 3 semanas. Sua genitora afirma que inicialmente eram poucas, que vem aumentando seu número e que são assintomáticas. Qual a hipótese diagnóstica mais provável e qual a melhor conduta a ser tomada para Jéssica?","options":{"A":"Prurigo estrófulo, devendo ser utilizado corticoide tópico.","B":"Nódulo escabiótico, devendo ser utilizado anti-histamínico.","C":"Molusco contagioso, devendo ser realizada curetagem das lesões.","D":"Verruga filiforme, devendo ser utilizada solução à base de ácidos salicílico e lático.","E":"Condiloma acuminado, devendo ser utilizada solução à base de ácidos salicílico e lático."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314780","ankiGuid":"eky}.@|i]("},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-954ecb551da8f50b","number":"0255x","sourceNumber":"0255x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Outros fatores necessitam ser considerados no momento da decisão terapêutica das lesões induzidas pelo HPV, como preferência do paciente, custos, disponibilidade de recursos, conveniência, efeitos adversos e experiência do profissional de saúde. Sobre isso, está inadequado o item:","options":{"A":"As verrugas anogenitais localizadas em superfícies úmidas e/ou nas áreas intertriginosas respondem pior à terapêutica tópica (ex.: ácido tricloroacético – ATA, podofilina) que as verrugas em superfícies secas.","B":"Deve-se mudar de opção terapêutica quando um paciente não apresentar melhora significativa após três sessões, ou se as verrugas não desaparecerem após seis sessões.","C":"Menos frequentemente, podem estar presentes em áreas extragenitais, como conjuntivas, mucosa nasal, oral e laríngea.","D":"A infecção por um genótipo de HPV não impede a infecção por outros tipos de HPV. O tratamento deve basear- se nos mesmos princípios referidos para os não- imunossuprimidos."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314781","ankiGuid":"pS(3&Jg:x|"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-666edcb36abb2ac4","number":"0256x","sourceNumber":"0256x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"O objetivo principal do tratamento das lesões anogenitais induzidas pelo HPV é a remoção das lesões clínicas. Não sendo adequado o seguinte item:","options":{"A":"Se não houver esse tratamento, os condilomas podem desaparecer, permanecer inalterados ou aumentar em tamanho ou número.","B":"Nenhuma evidência indica que os tratamentos disponíveis erradicam ou afetam a história natural da infecção do HPV.","C":"Como o carcinoma escamoso costuma surgir mais raramente em imunossuprimidos, valoriza-se a biópsia de lesões nesse grupo.","D":"O tratamento das lesões anogenitais induzidas pelo HPV deve ser individualizado, considerando tamanho, morfologia, número e local das lesões."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314782","ankiGuid":"AEYwEMm/:y"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-8ed74ccaf425cb36","number":"0257x","sourceNumber":"0257x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Quanto ao líquen escleroso vulvar, é correto afirmar que:","options":{"A":"apresenta lesões planas, pruriginosas e esverdeadas.","B":"é causado geralmente pelo HPV tipo 8 e 16.","C":"o corticoide tópico está contraindicado.","D":"a etiologia é incerta e o risco de aparecimento de câncer vulvar é inferior a 5%.","E":"é mais frequente durante a menacme, sendo raro na infância e na pós-menopausa."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314783","ankiGuid":"kLFM4;j%!="},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-fee72d0a02bbb24d","number":"0258x","sourceNumber":"0258x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Durante exame físico de uma paciente de 70 anos, com prurido vulvar há vários anos, identificou-se na vulva uma lesão avermelhada, com bordas elevadas e halo de epitélio branco. Qual a conduta mais adequada?","options":{"A":"Solicitar colposcopia pelo risco evidente de infecção por HPV de alto grau.","B":"Tratar o prurido com anti-histamínicos sistêmicos.","C":"Reavaliar a lesão após 30 dias de estrógeno tópico devido a menopausa.","D":"Realizar cauterização com laser de CO2.","E":"Realizar biópsia com anestesia local."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314784","ankiGuid":"fN!Y0}Mq5B"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-ded0e77d263187a1","number":"0259x","sourceNumber":"0259x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Mãe procura a UBS pois notou alteração na genitália de sua filha de 2 anos, relatando\"fechamento\" da vagina. Ao exame físico, nota-se que os pequenos lábios estão unidos por uma linha fina distinta de demarcação ou rafe entre eles. Feito o diagnóstico de sinéquia labial, assinale a alternativa correta:","options":{"A":"A causa da aderência labial é desconhecida, embora o hiperestrogenismo esteja envolvido.","B":"O tratamento das sinéquias labiais varia de acordo com o grau de fibrose e os sintomas, raramente apresentado resolução espontânea.","C":"A separação manual da sinéquia labial em ambiente ambulatorial, sem analgesia, é recomendada.","D":"A secção de lábios fundidos, também chamada introitoplastia, pode ser realizada em casos selecionados, envolvendo incisão em linha média com eletrocautério, sendo posteriormente suturado com fio absorvível.","E":"Essa aderência desenvolve-se em 1 a 5% das meninas de qualquer idade na fase pré- puberal e em cerca de 10% dos lactentes do sexo feminino no primeiro ano de vida."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314785","ankiGuid":"l>K#4PX$+Q"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-a90b7f27b0f28cba","number":"0260x","sourceNumber":"0260x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Paciente de 60 anos comparece ao ambulatório de ginecologia com queixa de prurido vulvar. Ao exame ginecológico, apresenta vulva atrófica, com presença de mácula hipocrômica em face interna de grandes lábios bilateralmente que se estende até região perineal e perianal. Nesse caso, o diagnóstico mais provável é de:","options":{"A":"psoríase","B":"líquen escleroso","C":"candidíase vulvar","D":"dermatite seborreica"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314786","ankiGuid":"DB-EkABzoz"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-946c612ccae415e7","number":"0261x","sourceNumber":"0261x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Mulher de 37 anos de idade refere aparecimento de \"bolinha\" na vulva há 1 semana, que limita a deambulação e a atividade sexual. A inspeção genital está mostrada abaixo.\n\nQual é o tratamento adequado para o caso?","options":{"A":"Aspirado por punção.","B":"Biópsia por agulha grossa.","C":"Marsupialização.","D":"Ressecção ampla com margem livre."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":["question_bank/media/ginecologia-doencas-de-vulva-e-vagina/paste-3b4f132ff86fe18f9579c5381442278f8dd27e30.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314787","ankiGuid":"n}9}fKC9~{"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-af46636b1f8a108e","number":"0262x","sourceNumber":"0262x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"O câncer de vulva, é raro, sendo responsável por 3 a 5% das neoplasias malignas do trato genital feminino, o que corresponde a menos de 1% dessas neoplasias. Em relação a essa neoplasia, é correto afirmar:","options":{"A":"o câncer de vulva pode se disseminar a partir do sítio inicial por meio da invasão local, mas a disseminação se dá principalmente por via hematogênica, atingindo pulmões, fígado e ossos.","B":"a localização mais comum da lesão é no pequeno lábio, com taxa de incidência de 50%; em seguida, na fúrcula, com incidência entre 15% a 20%, no clitóris e na glândula de Bartholin.","C":"o tipo histológico mais frequente é o carcinoma epidermoide, responsável por, aproximadamente, 85% das ocorrências, seguido pelo melanoma.","D":"a incidência estimada é de 10 a 20 casos por 100.000 mulheres/ano, com maior frequência entre mulheres com idade superior a 60 anos, quando a taxa aumenta para 50 casos por 100.000 mulheres/ano."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314788","ankiGuid":"e|99rgj>la"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-cd5d2dd833ab51ce","number":"0263x","sourceNumber":"0263x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"O tratamento do líquen escleroso vulvar:","options":{"A":"Não necessita de biópsia prévia.","B":"Com androgênios é a melhor alternativa.","C":"Obtém boa resposta terapêutica em menos da metade dos casos.","D":"Deve ser realizado de preferência com corticosteróides de alta potência.","E":"A vulvectomia é a primeira opção."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314789","ankiGuid":"E]A`r1EHJm"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-8f2f8ab1a414be7a","number":"0264x","sourceNumber":"0264x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Qual das alternativas, a seguir, informa a doença vulvar crônica com maior risco de malignidade?","options":{"A":"Líquen simples crônico.","B":"Líquen escleroso.","C":"Doença de Behçet.","D":"Líquen plano."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314790","ankiGuid":"lRG%Bx-$?0"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-cf296bc441f35ff5","number":"0265x","sourceNumber":"0265x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Uma paciente de 70 anos, com lesão ulcerada no terço médio do grande lábio esquerdo, de 1,5 cm no maior diâmetro e com linfonodos inguinais clinicamente negativos, recebeu diagnóstico por biópsia de carcinoma escamoso de vulva com invasão do estroma menor que 1,0 mm³. O tratamento adequado para essa paciente, de acordo com o estágio dessa lesão, é:","options":{"A":"Excisão local ampla.","B":"Vulvectomia radical.","C":"Hemivulvectomia com uretrectomia segmentar distal.","D":"Excisão local ampla com linfadenectomia inguinofemoral bilateral."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314791","ankiGuid":"nB5%T1S?c>"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-6e45aef6932b4492","number":"0266x","sourceNumber":"0266x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Estão relacionados com a epidemiologia de câncer basalóide ou verrucoso da vulva, exceto:","options":{"A":"Mulheres abaixo de 55 anos","B":"Baixo nível sócioeconômico","C":"HPV oncogênico","D":"Tabagismo","E":"Liquen escleroso"},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314792","ankiGuid":"F?yn7N<[Z."},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-33a065cd54487994","number":"0267x","sourceNumber":"0267x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Mãe procura o ambulatório de ginecologia trazendo filha de 7 (sete) anos que apresenta ao exame da região genital, lesão hipopigmentada, simétrica, com pele atrófica com aspecto de pergaminho e fissuras. Qual é o possível diagnóstico:","options":{"A":"Herpes simples","B":"Cancroide","C":"Linfogranuloma venéreo","D":"Líquen escleroso","E":"Molusco contagioso"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314793","ankiGuid":"I^gy|Gl3~b"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-3405db3919f6ce73","number":"0268x","sourceNumber":"0268x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Assinale a opção que indica o agente causador do condiloma acuminado:","options":{"A":"Papilomavirus","B":"Dermatófitos","C":"Herpesvírus","D":"Parvovírus","E":"Zontevirus"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314794","ankiGuid":"h^3L.4Q)V:"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-9ccce4018cce7282","number":"0269x","sourceNumber":"0269x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Com relação aos cistos da glândula de Bartholin, assinale a alternativa CORRETA.","options":{"A":"Quanto a sua etiopatologia, podemos afirmar que as bactérias mais comumente encontradas são a Neisseria gonorrhoeae e Chlamydia trachomatis.","B":"Devemos extirpá-los independentemente do seu tamanho, pois, no período de excitação sexual da mulher, eles se tornam muito volumosos e dolorosos.","C":"A terapia com antibióticos, após incisão e drenagem dos cistos de Bartholin, deve ser usada até mesmo nos casos em que a celulite não esteja presente.","D":"Quando o tratamento inclui incisão e drenagem, marsupialização, em mulheres com 40 anos ou mais, recomenda- se a biópsia devido ao risco de adenocarcinoma de Bartholin.","E":"O epitélio de transição dos ductos e os traumas não são considerados fatores etiológicos."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314795","ankiGuid":"NiR/RST51:"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-53665b7c1e915ef3","number":"0270x","sourceNumber":"0270x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"O cisto de Gardner localiza-se no(a):","options":{"A":"Canal cervical uterino.","B":"Ovário.","C":"Parede lateral da vagina.","D":"Porção distal das tubas uterinas."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314796","ankiGuid":"I?UX+n.xvr"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-85b4af716ba18d55","number":"0271x","sourceNumber":"0271x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Mulher de 65 anos com carcinoma de vulva invasivo com 3 cm de diâmetro sem evidência de disseminação linfática. Qual deve ser o tratamento inicial de escolha?","options":{"A":"Quimioterapia.","B":"Radioterapia.","C":"Vulvectomia simples.","D":"Vulvectomia radical sem linfadenectomia inguinal.","E":"Vulvectomia radical parcial com linfadenectomia inguinal bilateral."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314797","ankiGuid":"N;|Tx2KZFe"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-0a3409cff4865a64","number":"0272x","sourceNumber":"0272x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Das seguintes lesões vulvares, qual é considerada como Neoplasia?","options":{"A":"Lipoma.","B":"Hidroadenoma papilar.","C":"Fibroma.","D":"Doença de Paget vulvar."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314798","ankiGuid":"cTO~.XBdh:"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-efb766977cdcb3c1","number":"0273x","sourceNumber":"0273x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Qual o tratamento de escolha para o líquen vulvar crônico simples?","options":{"A":"Creme de clotrimazol 10 mg/g.","B":"Prednisona oral, 10 mg/dia.","C":"Imunoterapia.","D":"Pomada de propionato de clobetasol 0,05%.","E":"Metronidazol oral ou tópico."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314799","ankiGuid":"y(XD;t<@<`"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-640e6ba218866ecb","number":"0274x","sourceNumber":"0274x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"G.L.S., 60 anos, procura o serviço devido história de prurido vulvar crônico. Ao exame físico, presença de áreas hipocrômicas na vulva com lesão única de aspecto verrucoso. Tem citologia negativa. Provável diagnóstico (s) e conduta:","options":{"A":"Condiloma; biópsia.","B":"Condiloma; cauterização da lesão.","C":"Candidíase e condiloma; antifúngico e biópsia.","D":"Líquen esclero-atrófico e niv; vulvoscopia.","E":"Vulvite diabética; controle do diabetes."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314800","ankiGuid":"xMQk99MZyK"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-04f6f10edaf81dc6","number":"0275x","sourceNumber":"0275x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Mulher de 60 anos, na menopausa, apresenta pápulas atróficas esbranquiçadas, que coalescem em determinadas regiões com formação de placas de \"porcelana\" e distorcem a anatomia normal. Após biópsia da área em questão e confirmação da hipótese diagnóstica, o médico deve iniciar o tratamento com:","options":{"A":"Metronidazol gel a 0,75%, com aplicação uma vez ao dia, durante uma semana.","B":"Clindamicina creme 2%, com aplicação uma vez ao dia, durante quatro semanas.","C":"Testosterona gel 12,5 mg, com aplicação na lesão duas vezes ao dia, durante uma semana.","D":"Propionato de clobetasol a 0,05%, com aplicação na lesão duas vezes ao dia, durante quatro semanas."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314801","ankiGuid":"g%zXs{8pZo"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-7709fc4b7fb60817","number":"0276x","sourceNumber":"0276x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"A Bartolinite é uma infeção comum da mulher no menacme e pode surgir de maneira repentina. Quais os achados sugestivos de Bartolinite ao exame físico:","options":{"A":"Massa vulvar próximo à uretra.","B":"Celulite da pele do pequeno lábio próximo ao introíto vaginal (às 5 horas).","C":"Massa ao toque profundo com palpação abdominal.","D":"Linfonodos na região inguinal."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314802","ankiGuid":"fdNiWN5+^j"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-359ab14cbb0fa74d","number":"0277x","sourceNumber":"0277x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Prurido vulvar é uma queixa frequente no consultório. Ao examinar uma paciente com história de prurido vulvar há 2 anos, queixa de dispaurenia, história de outras alergias (incluindo dermatite de contato por bijuterias) e uso de pomadas e cremes com corticoides (baixa potência) para melhora do prurido, você identifica a presença de 3 placas espessadas e esbranquiçadas no pequeno lábio direito, perto do clitóris. A paciente relata que em uma consulta anterior, há 6 meses, o médico já havia informado que existia uma placa. Diante disso você deve:","options":{"A":"Ficar tranquilo e orientar a paciente que se trata do mesmo problema que ela tem no restante do corpo.","B":"Trocar a medicação para corticoides de alta potência.","C":"Explicar à paciente que nesse caso é comum aparecer novas lesões devido à alergia.","D":"Fazer uma biópsia para identificar, do ponto de vista anatomopatológico, o problema da paciente."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314803","ankiGuid":"ApP?q*l}q6"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-226c99a162c9cb86","number":"0278x","sourceNumber":"0278x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Para realização de biópsia de vulva, utiliza-se para orientação, o teste de Collins, que é feito com:","options":{"A":"Lugol e ácido acético.","B":"Solução de Shiller e hidróxido de potássio.","C":"Azul de toluidina e ácido acético.","D":"Lugol e azul de toluidina.","E":"Solução de Shiller e azul de toluidina."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314804","ankiGuid":"G=5nQC^7+]"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-df8ab5b32075540d","number":"0279x","sourceNumber":"0279x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"O fator prognóstico isolado mais importante no câncer de vulva é:","options":{"A":"profundidade de invasão tecidual","B":"metástase linfonodal","C":"tamanho da lesão","D":"grau nuclear"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314805","ankiGuid":"jV%en2lxNr"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-9d180109f1c520e4","number":"0280x","sourceNumber":"0280x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"A patologia caracterizada por lesões cutaneomucosas (ocular, oral e genital), associada à vasculite sistêmica, é denominada como:","options":{"A":"Acantose nigricante.","B":"Doença de Crohn.","C":"Doença de Behçet.","D":"Líquen plano.","E":"Líquen escleroatrófico."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314806","ankiGuid":"x&k?^F<Qz|"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-5a0f4df9158d4f90","number":"0281x","sourceNumber":"0281x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Durante o climatério também é importante a avaliação periódica objetivando-se diagnosticar precocemente enfermidades decorrentes de doenças sexualmente transmissíveis. Assim, relativa às doenças atípicas do trato genital inferior, pode-se afirmar que:","options":{"A":"A colposcopia, evidenciando mosaico grosseiro irregular, relaciona-se à infecção pelo HIV.","B":"O câncer epidermoide vulvar associa-se, comumente, ao líquen escleroso da vulva.","C":"O carcinoma epidermoide cervical não é lesão HPV-induzida.","D":"Colpocitologia oncótica positiva significa conização como passo seguinte.","E":"A lesão intraepitelial vulvar de alto grau relaciona-se diretamente ao herpes-vírus."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314807","ankiGuid":"i#^_9.J.eW"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-51f2ba1ec211db26","number":"0282x","sourceNumber":"0282x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"O câncer de vulva é um tumor maligno que atinge a parte externa do aparelho reprodutor feminino. A vulva é formada pelos lábios maiores, lábios menores, clitóris e intróito vaginal. Na vulva está localizada a abertura da uretra, canal que conduz urina da bexiga ao meio externo. Câncer da vulva é uma neoplasia rara, responsável por 0,5% de todos os cânceres nas mulheres e 5% dos tumores ginecológicos. Aproximadamente 90% dos cânceres de vulva são carcinomas epidermóides. Os demais casos compreendem adenocarcinomas, melanomas, sarcomas e carcinomas basocelulares. Em relação ao câncer de vulva, os linfonodos mais frequentemente acometidos são os:","options":{"A":"Ilíacos externos.","B":"Ilíacos comuns.","C":"Inguinofemorais.","D":"Para-aórticos.","E":"Pélvicos."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314808","ankiGuid":"CxtKOPjnjv"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-94202440509beb2d","number":"0283x","sourceNumber":"0283x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Observe a imagem abaixo para responder à questão (Conforme imagem do caderno de questões). Paciente de 29 anos, refere aparecimento de “bolinhas” na vulva há 1 semana. No exame físico, evidenciaram lesões expostas na imagem acima.\n\nO tratamento indicado para o caso acima, é","options":{"A":"Aciclovir.","B":"Ácido Bórico.","C":"Ácido Acético.","D":"Ácido Tricloroacético.","E":"Metotrexate."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":["question_bank/media/ginecologia-doencas-de-vulva-e-vagina/paste-e40a053049279051b3a72409c376ee67fd4250ec.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314809","ankiGuid":"b,l#Y(N{nG"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-456b8b3cb0b71123","number":"0284x","sourceNumber":"0284x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Sobre a fase do climatério relativa às doenças atípicas do trato genital inferior, atribua V (verdadeiro) ou F (falso) às afirmativas a seguir. ( ) Colposcopia, evidenciando mosaico grosseiro irregular, relaciona-se à infecção pelo HPV; ( ) O câncer epidermoide vulvar associa-se, comumente, ao líquen escleroso da vulva; ( ) O carcinoma epidermoide cervical é lesão HPV-induzida; ( ) Colpocitologia oncótica positiva significa conização como passo seguinte; ( ) A lesão intraepitelial vulvar de alto grau relaciona-se diretamente ao herpes-vírus. Assinale a alternativa que contém, de cima para baixo, a sequência correta.","options":{"A":"V, V, V, F, F.","B":"V, F, V, V, F.","C":"V, F, F, V, F.","D":"F, V, V, F, V.","E":"F, F, F, V, V."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314810","ankiGuid":"bYu&X_8ir0"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-911e169bdca6c2bd","number":"0285x","sourceNumber":"0285x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Durante a gestação, devemos tratar os condilomas acuminados com:","options":{"A":"Solução de podofilina a 4% em gel.","B":"Creme de 5-fluorouracil a 5%.","C":"Pomada de podofilotoxina, para inativar o vírus.","D":"Diatermocauterização das lesões ou ácido tricloroacético a 70%.","E":"Solução de ácido metacresossulfônico ou ATA a 60%."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314811","ankiGuid":"s^+A,eU/MO"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-3f4fd728f8c2e47d","number":"0286x","sourceNumber":"0286x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Sobre as doenças que acometem a vulva, é CORRETO afirmar que:","options":{"A":"A doença de Paget vulvar é a neoplasia mais frequente da vulva e apresenta crescimento rápido","B":"O câncer de vulva acomete as pacientes principalmente durante a menacme","C":"O tipo histológico que acomete as pacientes idosas tem íntima relação com infecção pelo vírus HPV","D":"O carcinoma de células escamosas tem como tratamento convencional a excisão cirúrgica vulvar e linfadenectomia inguinofemoral"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314812","ankiGuid":"Lh[6bWF*8,"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-7ff03d5b3b4aa043","number":"0287x","sourceNumber":"0287x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Uma criança de dois anos com sangramento vaginal leve e corrimento fétido, com lesão polipoide e friável em fundo de saco vaginal, que à ultrassonografia se apresenta como tumoração complexa de 2cm em parede fúndica-lateral esquerda, tem como hipótese diagnóstica mais provável:","options":{"A":"Corpo estranho.","B":"Tumor botrioide.","C":"Vaginite granulomatosa","D":"Sarcoma vaginal."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314813","ankiGuid":"O.;9.?>q~g"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-f6ba76fa1b036242","number":"0288x","sourceNumber":"0288x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Paciente de 55 anos queixa-se de prurido vulvar intenso há vários anos que, por vezes, interfere no sono. Ao exame, apresenta lesão brancacenta bem delimitada, envolvendo vulva e ânus, em forma de “8”. Ao exame especular, a mucosa vaginal está íntegra. Neste caso:","options":{"A":"A hipótese mais provável é líquen plano.","B":"A biópsia é obrigatória para confirmar o diagnóstico.","C":"O tratamento de escolha é o corticoide tópico de alta potência.","D":"A alta ambulatorial é programada após a remissão dos sintomas."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314814","ankiGuid":"CINCA30AY-"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-f816ffefd49966b0","number":"0289x","sourceNumber":"0289x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Mulher de 23 anos de idade apresentou no passado diagnóstico de lesão de baixo grau no colo uterino e foi submetida a tratamento destrutivo. Atualmente apresenta esfregaço cervicovaginal de lesão de alto grau.\n\nOnde está a lesão e qual a conduta?","options":{"A":"Na parede vaginal direita e deverá ser biopsiada.","B":"No fórnice vaginal e deve ser mantida em observação.","C":"No canal endocervical e a conduta é expectante.","D":"No canal endocervical e deve-se biopsiar.","E":"No septo embriológico residual e deve-se realizar vaginoplastia."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":["question_bank/media/ginecologia-doencas-de-vulva-e-vagina/paste-4eea2357dbd2389a4fb4f4d44c9b4a1a2c7f9e5f.png","question_bank/media/ginecologia-doencas-de-vulva-e-vagina/paste-c56ff1bc237243915b54a7fe041f1f2bb6da2ce5.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314815","ankiGuid":"l@RX8`_EdP"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-b1aaafda6a93848f","number":"0290x","sourceNumber":"0290x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Dentre os abaixo, qual NÃO se constitui em fator de risco para neoplasia intraepitelial vaginal (NIVA)?","options":{"A":"Tratamento prévio para neoplasia intraepitelial.","B":"Radioterapia prévia para câncer de colo uterino.","C":"Tabagismo.","D":"Adenose vaginal."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314816","ankiGuid":"IA%!c?rwrq"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-67c139714f288e67","number":"0291x","sourceNumber":"0291x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"M. J., 27 anos, solteira, gestação, parto e aborto zero. Tabagista. Vida sexual ativa. Usa o anticoncepcional Depo-provera. Procurou a Unidade Básica de Saúde (UBS) para avaliar o aparecimento de lesão vulvar, vegetante, pruriginosa há 2 semanas, que vem aumentando em número e tamanho. Após avaliação do exame clínico, o médico diagnosticou condiloma vulvar. Para o tratamento dessa condição clínica, pode-se afirmar que NÃO se usa:","options":{"A":"Eletrocautério.","B":"Aplicação de Ácido Acético 5%.","C":"Aplicação de Podofilina.","D":"Criocautério."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314817","ankiGuid":"vM4}onN,A&"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-23bc0e6fd6b321a1","number":"0292x","sourceNumber":"0292x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Mulher de 20 anos, G1P0, 36 semanas de idade gestacional, chega à consulta do Projeto Nascer referindo aparecimento de uma lesão verrucosa crescente em região vulvar (VER IMAGEM), sem tratamento pelo ginecologista da UBS.\n\nA paciente refere dificuldade de deambulação. Biópsia do local mostra células sem características de malignidade, com vacúolos citoplasmáticos perinaviculares e núcleos de grande diâmetro. Sobre a doença clínica apresentada na imagem, assinale a opção INCORRETA:","options":{"A":"Existe um risco elevado de papilomatose laríngea caso a via obstétrica seja a vaginal, devido ao tamanho e à carga viral da lesão.","B":"O tratamento com imiquimode poderia ser uma ótima opção para essa paciente, com potencial regressão da lesão e possibilidade da via obstétrica.","C":"A cesariana seria a melhor opção para essa paciente, pois não haveria tempo de regressão após tratamento cirúrgico com exérese da lesão.","D":"A doença apresenta mais de 120 sorotipos, sendo 40 deles voltados para a região genital. O subtipo apresentado poderia ser o tipo 6 e 11.","E":"A eletrocauterização não é tratamento indicado durante a gestação."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":["question_bank/media/ginecologia-doencas-de-vulva-e-vagina/paste-ded4d3ee1f86f433cec48fa08b5ac38021c1adc6.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314818","ankiGuid":"h<9),lF*HF"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-12f26898d6bb6d0d","number":"0293x","sourceNumber":"0293x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"O carcinoma espinocelular corresponde a menos de 20% dos carcinomas de vulva, porque o carcinoma de vulva mais prevalente é o adenocarcinoma.","options":{"A":"As duas assertivas estão incorretas.","B":"A primeira assertiva está correta e a segunda está incorreta.","C":"A primeira assertiva está incorreta e a segunda está correta.","D":"As duas assertivas estão corretas e a segunda não justifica a primeira.","E":"As duas assertivas estão corretas e a segunda justifica a primeira."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314819","ankiGuid":"zYXVJ_q@3!"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-2bc55f7dbe6cb392","number":"0294x","sourceNumber":"0294x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Líquen escleroso e uma dermatose mais comum em que faixa de idade feminina:","options":{"A":"Pré-púbere.","B":"Puerpério.","C":"Pós-menopausa.","D":"Menacme com vida sexual ativa.","E":"Jovem após a menarca."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314820","ankiGuid":"y7f?$WaWZ,"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-90f2f254f76bf0af","number":"0295x","sourceNumber":"0295x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Sobre o câncer de vulva é CORRETO afirmar:","options":{"A":"Prurido vulvar e vulvodínea são manifestações clínicas incomuns.","B":"O melanoma é o tipo histológico mais frequente.","C":"O carcinoma verrucoso é uma variante do carcinoma epidemoide e tende a dar metástase linfonodal.","D":"Pode estar relacionado à infecção pelo HPV."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314821","ankiGuid":"l?6x*t#9}^"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-b481f82e8ff85aa1","number":"0296x","sourceNumber":"0296x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"O tratamento do líquen escleroso da vulva tem o objetivo de prevenir:","options":{"A":"Alterações anatômicas e transformação maligna.","B":"Tricomoníase e candidíase recorrente.","C":"Transformação maligna e tricomoníase.","D":"Vaginose bacteriana e alterações anatômicas.","E":"Candidíase recorrente e vaginose bacteriana."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314822","ankiGuid":"b*7w@c;t>9"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-0e79988b71af2219","number":"0297x","sourceNumber":"0297x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"No câncer de vulva, as metástases para linfonodos intrapélvicos são mais observadas, quando a localização é","options":{"A":"Pequenos lábios.","B":"Grandes lábios.","C":"Clitoridiana.","D":"Perineal.","E":"Fúrcula."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314823","ankiGuid":"FGYQs37o_@"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-d93f8a37acb36c7e","number":"0298x","sourceNumber":"0298x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Uma mulher de 58 anos procura o consultório médico devido prurido vulvar. No exame ginecológico da genitália, você observa uma pele fina, parecendo enrugada, atrófica, coloração esbranquiçada em toda vulva. Dos diagnósticos abaixo, qual é o diagnóstico mais provável:","options":{"A":"Dermatite de contato.","B":"Psoríase vulvar.","C":"Acrocórdon de vulva.","D":"Líquen escleroso de vulva.","E":"Vulvite atrófica."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314824","ankiGuid":"P-9rHrerHe"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-e3cbb94e74407871","number":"0299x","sourceNumber":"0299x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Paciente queixa-se de prurido vulvar iniciado há cinco anos. Ao exame, observa-se mancha hipocrômica extensa acometendo face interna dos lábios maiores e apagamento dos lábios menores, com lesão ulcerada próxima ao clitóris. A hipótese diagnóstica e conduta imediata são:","options":{"A":"Sífilis / Administrar penicilina benzatina.","B":"Herpes genital / Aplicar aciclovir.","C":"Câncer de vulva / Realizar biópsia da lesão.","D":"Donovanose / Prescrever vibramicina.","E":"Doença de Behçet / Tratar com corticoide."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314825","ankiGuid":"Q=Pty5jn1w"},{"id":"anki-ginecologia-doencas-de-vulva-e-vagina-458b59f40c9f4cf9","number":"02100x","sourceNumber":"02100x","collectionBlock":"anki:ginecologia-doencas-de-vulva-e-vagina","collectionLabel":"Anki · Doenças de Vulva e Vagina","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças de Vulva e Vagina","subtopic":"","stem":"Associe a sintomatologia ao diagnóstico e assinale a alternativa correta:\n1 - Sangramento genital pós-menopausa;\n2- Sinusorragia;\n3 - Dor Abdominal esporádica;\n4 - Dietilestibestrol (DES);\n5 - Beta-hCG.\n\nI. Cancer de colo uterino;\nII Cancer de ovário;\nIII. Cancer de endométrio;\nIV. Neoplasma trofoblástrica;\nV. Adenose Vaginal.","options":{"A":"1-III; 2-I; 3-IV; 4II; 5-V.","B":"1-II; 2-V; 3-I; 4-III; 5-IV.","C":"1-IV; 2-V; 3-I; 4-III; 5-V.","D":"1-II; 2-III; 3-I; 4-V; 5-IV.","E":"1-III; 2-I; 3-II; 4-V;5-IV."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças de Vulva e Vagina","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças de Vulva e Vagina","Anki"],"ankiNoteId":"1780580314826","ankiGuid":"sZ6W)JS1Ti"}]};
